frappe.ready(function() {
    const urlParams = new URLSearchParams(window.location.search);
    const token = urlParams.get('token');

    function showStatusMessage(title, message, isError = true) {
        $('#gate-pass-web-form').hide();

        let icon = isError ? '⚠️' : '✅';
        let bgColor = isError ? '#fdf2f2' : '#f0fdf4';
        let borderColor = isError ? '#f87171' : '#4ade80';
        let titleColor = isError ? '#9b1c1c' : '#166534';
        let textColor = isError ? '#771d1d' : '#15803d';

        let statusHtml = `
            <div style="max-width: 500px; margin: 40px auto; padding: 25px; text-align: center; border: 1px solid ${borderColor}; background-color: ${bgColor}; border-radius: 12px; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);">
                <div style="font-size: 36px; margin-bottom: 12px;">${icon}</div>
                <h3 style="color: ${titleColor}; margin-bottom: 8px; font-weight: 700; font-size: 1.25rem;">${title}</h3>
                <p style="color: ${textColor}; font-size: 0.95rem; margin: 0; line-height: 1.5;">${message}</p>
            </div>
        `;

        $('#response-status-msg').html(statusHtml).show();
    }

    frappe.call({
        method: "visitor_management_knk.visitors_management.doctype.visitor_invitation.visitor_invitation.get_active_employees",
        callback: function(r) {
            if (r.message) {
                let $select = $('#person_to_visit');
                $select.empty().append('<option value="">Select Person to Visit</option>');

                r.message.forEach(function(emp) {
                    let displayName = emp.first_name || emp.employee_name;
                    let deptText = emp.department ? ` (${emp.department})` : '';

                    $select.append(
                        `<option value="${emp.name}" data-dept="${emp.department || ''}">` +
                        `${displayName}${deptText}` +
                        `</option>`
                    );
                });

                if (window.pendingHostEmployee) {
                    $select.val(window.pendingHostEmployee).trigger('change');
                }
            }
        }
    });

    $('#person_to_visit').on('change', function() {
        let selectedDept = $(this).find(':selected').data('dept');
        if (selectedDept !== undefined) {
            $('#department').val(selectedDept);
        }
    });

    $('.vpk-file-input').on('change', function() {
        let fileName = this.files[0] ? this.files[0].name : '';
        $(this).siblings('.vpk-file-wrapper').find('.vpk-file-name').text(fileName);
    });

    if (!token) {
        showStatusMessage("Invalid Link", "No access token provided. Please open the link sent to your email.");
    } else {
        frappe.call({
            method: "visitor_management_knk.visitors_management.doctype.visitor_invitation.visitor_invitation.get_invitation_details",
            args: { token: token },
            callback: function(r) {
                if (r.message) {
                    if (r.message.is_expired || r.message.status === 'Expired') {
                        showStatusMessage("Invitation Link Expired", "This registration form link has expired. Please contact your host employee to request a new invitation link.");
                        return;
                    }

                    if (r.message.host_employee) {
                        window.pendingHostEmployee = r.message.host_employee;
                        $('#person_to_visit').val(r.message.host_employee).trigger('change');
                    }

                    if (r.message.visitor_type) {
                        $('#visitor_type').val(r.message.visitor_type).prop('disabled', true);
                    }

                    if (r.message.visitor_email) {
                        $('#email_id').val(r.message.visitor_email).prop('readonly', true);
                    }

                    if (r.message.visit_date) {
                        $('#visit_date').val(r.message.visit_date).prop('readonly', true);
                    }
                }
            },
            error: function(r) {
                showStatusMessage("Invitation Link Expired", "This registration form link has expired or is invalid. Please contact your host employee to request a new invitation link.");
            }
        });
    }

    function fileToBase64(fileObj, callback) {
        if (!fileObj) {
            callback(null);
            return;
        }
        let reader = new FileReader();
        reader.onload = function(e) {
            callback(e.target.result);
        };
        reader.onerror = function() {
            callback(null);
        };
        reader.readAsDataURL(fileObj);
    }

    $('#gate-pass-web-form').on('submit', function(e) {
        e.preventDefault();

        if (!token) {
            frappe.msgprint(__('Cannot submit: Invalid or missing invitation token.'));
            return;
        }

        $('#btn-submit-form').prop('disabled', true).text('Submitting Request...');

        let photoFile = $('#visitor_photo')[0] ? $('#visitor_photo')[0].files[0] : null;
        let idScanFile = $('#id_proof_scan')[0] ? $('#id_proof_scan')[0].files[0] : null;

        fileToBase64(photoFile, function(photoBase64) {
            fileToBase64(idScanFile, function(idScanBase64) {
                frappe.call({
                    method: "visitor_management_knk.visitors_management.doctype.visitor_invitation.visitor_invitation.submit_visitor_pass",
                    args: {
                        token: token,
                        full_name: $('#visitor_full_name').val(),
                        mobile: $('#mobile_number').val(),
                        email: $('#email_id').val(),
                        visitor_type: $('#visitor_type').val(),
                        id_type: $('#id_proof_type').val(),
                        id_number: $('#id_proof_number').val(),
                        person_to_visit: $('#person_to_visit').val(),
                        department: $('#department').val(),
                        visit_date: $('#visit_date').val(),
                        expected_checkin: $('#expected_checkin').val(),
                        expected_checkout: $('#expected_checkout').val(),
                        purpose: $('#purpose_of_visit').val(),
                        vehicle_number: $('#vehicle_number').val(),
                        visitor_items: $('#items').val(),
                        photo: photoBase64,
                        id_scan: idScanBase64
                    },
                    callback: function(r) {
                        if (r.message && r.message.status === "success") {
                            showStatusMessage(
                                "Registration Successful!", 
                                "Your Gate Pass request has been submitted successfully and sent for host approval.", 
                                false
                            );
                        } else {
                            $('#btn-submit-form').prop('disabled', false).text('Complete Registration & Request Gate Pass');
                        }
                    },
                    error: function(r) {
                        $('#btn-submit-form').prop('disabled', false).text('Complete Registration & Request Gate Pass');
                    }
                });
            });
        });
    });
});
